actions.script:
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const LEVELS = {EapRead: 1, EapSend: 2, EapManage: 3}
const PERMISSIONS = [null, 'EapRead', 'EapSend', 'EapManage']
accountList = []
accessMap = {}
level = 0
account = null
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) return
if (userId !== currentUserId) {
    const authzOff = ec.artifactExecution.authzDisabled()
    if (!authzOff) { ec.message.addError(`The email accounts of user ${userId} are not yours to see`); return }
}
const memberLevels = {}
for (const row of ec.entity.find('moqui.basic.email.EmailAccountUser').condition('userId', userId)
        .conditionDate('fromDate', 'thruDate', null).list()) {
    const rowLevel = LEVELS[row.permissionEnumId] || 1
    if (!(memberLevels[row.emailAccountId] >= rowLevel)) memberLevels[row.emailAccountId] = rowLevel
}
const memberIds = Object.keys(memberLevels)
const reach = [cf.makeCondition('ownerUserId', 'equals', userId)]
if (memberIds.length) reach.push(cf.makeCondition('emailAccountId', 'in', memberIds))
const rows = Array.from(ec.entity.find('moqui.basic.email.EmailAccount').condition(cf.makeCondition(reach, 'or'))
        .condition(cf.makeCondition('statusId', 'not-equals', 'EasRemoved', true)).list())
const defaultFiling = (kind) => kind === 'EakExternal' ? 'ErfLinkedOnly' : (kind === 'EakInternal' ? null : 'ErfAllMatches')
for (const row of rows) {
    const isOwner = row.ownerUserId === userId
    const rowLevel = isOwner ? 3 : (memberLevels[row.emailAccountId] || 0)
    if (rowLevel === 0) continue
    const isInternal = row.accountKindEnumId === 'EakInternal'
    accessMap[row.emailAccountId] = rowLevel
    accountList.push({emailAccountId: row.emailAccountId, ownerUserId: row.ownerUserId ?? null,
        ownerPartyId: row.ownerPartyId ?? null, accountKindEnumId: row.accountKindEnumId ?? null,
        emailServerId: row.emailServerId ?? null, ownsEmailServer: row.ownsEmailServer === 'Y',
        emailAddress: row.emailAddress ?? null, accountName: row.accountName ?? null, color: row.color ?? null,
        syncWindowDays: row.syncWindowDays ?? null,
        recordFilingEnumId: row.recordFilingEnumId || defaultFiling(row.accountKindEnumId),
        statusId: row.statusId || 'EasActive', lastSyncDate: toMillis(row.lastSyncDate), lastSyncError: row.lastSyncError ?? null,
        sequenceNum: row.sequenceNum ?? null, isOwner: isOwner, isInternal: isInternal, level: rowLevel,
        permissionEnumId: PERMISSIONS[rowLevel], canSend: rowLevel >= 2 && !isInternal, canManage: rowLevel >= 3})
}
accountList.sort((left, right) => {
    if (left.isInternal !== right.isInternal) return left.isInternal ? -1 : 1
    const leftSeq = left.sequenceNum ?? 999999, rightSeq = right.sequenceNum ?? 999999
    if (leftSeq !== rightSeq) return leftSeq - rightSeq
    const byName = String(left.accountName || left.emailAddress || '').localeCompare(String(right.accountName || right.emailAddress || ''))
    return byName !== 0 ? byName : String(left.emailAccountId).localeCompare(String(right.emailAccountId))
})
if (emailAccountId) {
    level = accessMap[emailAccountId] || 0
    account = accountList.find((candidate) => candidate.emailAccountId === emailAccountId) || null
}

created = false
emailAccountId = null
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) { ec.message.addError('No user for the Internal account'); return }
if (userId !== currentUserId) {
    const authzOff = ec.artifactExecution.authzDisabled()
    if (!authzOff) { ec.message.addError(`The Internal account of user ${userId} is not yours`); return }
}
const existing = ec.entity.find('moqui.basic.email.EmailAccount').condition('ownerUserId', userId)
        .condition('accountKindEnumId', 'EakInternal').orderBy('emailAccountId').limit(1).list()
if (existing.length) { emailAccountId = existing[0].emailAccountId; return }
const row = ec.entity.makeValue('moqui.basic.email.EmailAccount')
row.setSequencedIdPrimary()
row.setFields({ownerUserId: userId, accountKindEnumId: 'EakInternal', accountName: ec.l10n.localize('Internal'),
    statusId: 'EasActive', sequenceNum: 0}, true, null, null)
row.create()
emailAccountId = row.emailAccountId
created = true

const KINDS = ['EakHosted', 'EakExternal', 'EakShared']
if (!KINDS.includes(accountKindEnumId)) {
    ec.message.addError(accountKindEnumId === 'EakInternal' ? 'The Internal account is made by ensure#InternalAccount'
            : `Unknown account kind ${accountKindEnumId}`)
    return
}
const authzOff = ec.artifactExecution.authzDisabled()
if (!ec.user.userId && !authzOff) { ec.message.addError('No user for the email account'); return }
if (ownerUserId && ownerUserId !== ec.user.userId && !authzOff) { ec.message.addError('An email account is made for yourself'); return }
if (emailServerId && !authzOff) { ec.message.addError('An existing email server is chosen only by internal setup'); return }
if (!ownerUserId) ownerUserId = ec.user.userId
let ownsServer = false
if (emailServerId) {
    if (ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', emailServerId).count() === 0) {
        ec.message.addError(`Email server ${emailServerId} not found`); return }
} else if (smtpHost || storeHost) {
    const server = ec.entity.makeValue('moqui.basic.email.EmailServer')
    server.setSequencedIdPrimary()
    server.setFields({smtpHost: smtpHost, smtpPort: smtpPort, smtpStartTls: smtpStartTls || 'Y', smtpSsl: smtpSsl || 'N',
        storeHost: storeHost, storePort: storePort, storeProtocol: storeHost ? (storeProtocol || 'imaps') : null,
        storeFolder: storeFolder, storeDelete: 'N', storeMarkSeen: 'N', storeSkipSeen: 'N', mailUsername: mailUsername || emailAddress,
        mailPassword: mailPassword, authTypeEnumId: authTypeEnumId, oauthProviderEnumId: oauthProviderEnumId}, false, null, null)
    server.create()
    emailServerId = server.emailServerId
    ownsServer = true
}
const account = ec.entity.makeValue('moqui.basic.email.EmailAccount')
account.setSequencedIdPrimary()
account.setFields({ownerUserId: ownerUserId, ownerPartyId: ownerPartyId, accountKindEnumId: accountKindEnumId,
    emailServerId: emailServerId, ownsEmailServer: ownsServer ? 'Y' : 'N', emailAddress: emailAddress,
    accountName: accountName || emailAddress, color: color, syncWindowDays: syncWindowDays,
    recordFilingEnumId: recordFilingEnumId || (accountKindEnumId === 'EakExternal' ? 'ErfLinkedOnly' : 'ErfAllMatches'),
    statusId: 'EasActive', sequenceNum: sequenceNum}, false, null, null)
account.create()
emailAccountId = account.emailAccountId
const FOLDERS = [['EfkInbox', 'Inbox', 'INBOX'], ['EfkDrafts', 'Drafts', null], ['EfkSent', 'Sent', null],
    ['EfkArchive', 'Archive', null], ['EfkJunk', 'Junk', null], ['EfkTrash', 'Trash', null]]
FOLDERS.forEach(([kind, name, path], index) => {
    const folder = ec.entity.makeValue('moqui.basic.email.EmailFolder')
    folder.setSequencedIdPrimary()
    folder.setFields({emailAccountId: emailAccountId, folderKindEnumId: kind, folderName: ec.l10n.localize(name),
        folderPath: path, subscribed: 'Y', sequenceNum: index + 1}, false, null, null)
    folder.create()
})
const identity = ec.entity.makeValue('moqui.basic.email.EmailIdentity')
identity.setSequencedIdPrimary()
identity.setFields({emailAccountId: emailAccountId, emailAddress: emailAddress,
    displayName: displayName || accountName || ec.user.userAccount?.userFullName || null,
    signaturePlacementEnumId: 'EspBelowQuote', useForReplies: 'Y', isDefault: 'Y'}, false, null, null)
identity.create()
emailIdentityId = identity.emailIdentityId

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not change email account ${emailAccountId}`); return }
const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', emailAccountId).forUpdate(true).one()
const isInternal = account.accountKindEnumId === 'EakInternal'
const given = (value) => value != null
const blank = (value) => value === '' ? null : value
if (given(accountName)) account.set('accountName', blank(accountName))
if (given(color)) account.set('color', blank(color))
if (given(sequenceNum)) account.set('sequenceNum', blank(sequenceNum))
const serverFields = {smtpHost, smtpPort, smtpStartTls, smtpSsl, storeHost, storePort, storeProtocol, storeFolder,
    mailUsername, mailPassword, authTypeEnumId, oauthProviderEnumId}
const serverGiven = Object.keys(serverFields).filter((name) => given(serverFields[name]))
if (isInternal) {
    if (serverGiven.length || given(emailAddress) || given(syncWindowDays) || given(recordFilingEnumId) || given(statusId)) {
        ec.message.addError('The Internal account takes only a name, a color and a sequence'); return }
    account.update()
    return
}
if (given(emailAddress)) {
    if (!emailAddress) { ec.message.addError('An email account needs an address'); return }
    account.set('emailAddress', emailAddress)
}
if (given(syncWindowDays)) account.set('syncWindowDays', blank(syncWindowDays))
if (given(recordFilingEnumId)) account.set('recordFilingEnumId', blank(recordFilingEnumId))
if (given(statusId) && statusId !== account.statusId) {
    if (!['EasActive', 'EasPaused'].includes(statusId)) { ec.message.addError(`An account is set Active or Paused, not ${statusId}`); return }
    account.set('statusId', statusId)
}
emailServerId = account.emailServerId ?? null
if (serverGiven.length) {
    if (emailServerId && account.ownsEmailServer !== 'Y') {
        ec.message.addError(`Email account ${emailAccountId} uses a shared server, which is not changed through the account`); return }
    let server = emailServerId ? ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', emailServerId).one() : null
    const creating = server == null
    if (creating) {
        server = ec.entity.makeValue('moqui.basic.email.EmailServer')
        server.setSequencedIdPrimary()
        server.setFields({smtpStartTls: 'Y', smtpSsl: 'N', storeDelete: 'N', storeMarkSeen: 'N', storeSkipSeen: 'N',
            authTypeEnumId: 'EatPassword', mailUsername: account.emailAddress}, false, null, null)
    }
    for (const name of serverGiven) {
        if (name === 'mailPassword' && !mailPassword) continue
        server.set(name, blank(serverFields[name]))
    }
    if (creating) {
        server.create()
        emailServerId = server.emailServerId
        account.set('emailServerId', emailServerId)
        account.set('ownsEmailServer', 'Y')
    } else {
        server.update()
    }
}
account.update()

const cf = ec.entity.conditionFactory
deletedMessageCount = 0
keptMessageCount = 0
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not remove email account ${emailAccountId}`); return }
if (access.account.isInternal) { ec.message.addError('The Internal account is not removed'); return }
const now = ec.user.nowTimestamp
const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', emailAccountId).one()
const ownedServer = account.ownsEmailServer === 'Y' && account.emailServerId ? account.emailServerId : null
if (!deleteLocalCopies) {
    account.set('statusId', 'EasRemoved')
    account.update()
    ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', emailAccountId)
            .conditionDate('fromDate', 'thruDate', null).updateAll({thruDate: now})
    if (ownedServer) ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', ownedServer)
            .updateAll({mailPassword: null, oauthRefreshToken: null})
    keptMessageCount = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', emailAccountId).count()
    return
}
// the messages, a batch at a time, each batch in its own transaction; one another record refers to is kept
const result = ec.service.sync().name('org.moqui.impl.EmailClientServices.delete#AccountMessages')
        .parameter('emailAccountId', emailAccountId).disableAuthz().call()
if (ec.message.hasError()) return
deletedMessageCount = result.deletedCount || 0
keptMessageCount = result.keptCount || 0
const labelIds = Array.from(ec.entity.find('moqui.basic.email.EmailLabel').condition('emailAccountId', emailAccountId)
        .selectField('emailLabelId').list()).map((row) => row.emailLabelId)
if (labelIds.length) ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailLabelId', 'in', labelIds).deleteAll()
ec.entity.find('moqui.basic.email.EmailLabel').condition('emailAccountId', emailAccountId).deleteAll()
ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', emailAccountId)
        .condition('parentFolderId', 'not-equals', null).updateAll({parentFolderId: null})
ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', emailAccountId).deleteAll()
ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', emailAccountId).deleteAll()
ec.entity.find('moqui.basic.email.EmailRule').condition('emailAccountId', emailAccountId).deleteAll()
ec.entity.find('moqui.basic.email.EmailOutOfOffice').condition('emailAccountId', emailAccountId).deleteAll()
ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', emailAccountId).deleteAll()
account.delete()
if (ownedServer && ec.entity.find('moqui.basic.email.EmailAccount').condition('emailServerId', ownedServer).count() === 0)
    ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', ownedServer).deleteAll()

deletedCount = 0
keptCount = 0
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('delete#AccountMessages is internal'); return }
const BATCH = 200
const attempt = (ids) => {
    ec.message.pushErrors()
    ec.service.sync().name('org.moqui.impl.EmailClientServices.delete#LocalMessages')
            .parameter('emailMessageIdList', ids).requireNewTransaction(true).disableAuthz().call()
    const errors = ec.message.hasError() ? ec.message.errorsString : null
    ec.message.clearErrors()
    ec.message.popErrors()
    return errors
}
// the ids once, newest first (replies before the messages they answer), then a batch at a time
const allIds = Array.from(ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', emailAccountId)
        .selectField('emailMessageId').orderBy('-messageDate').orderBy('-emailMessageId').list()).map((row) => row.emailMessageId)
for (let start = 0; start < allIds.length; start += BATCH) {
    const ids = allIds.slice(start, start + BATCH)
    if (attempt(ids) == null) { deletedCount += ids.length; continue }
    for (const id of ids) {
        const errors = attempt([id])
        if (errors == null) { deletedCount++; continue }
        ec.logger.warn(`Email message ${id} of account ${emailAccountId} is not deleted, a record refers to it: ${errors}`)
        ec.message.pushErrors()
        ec.service.sync().name('org.moqui.impl.EmailClientServices.detach#LocalMessages')
                .parameter('emailMessageIdList', [id]).requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) ec.logger.log('error', `Could not take email message ${id} out of account ${emailAccountId}: ${ec.message.errorsString}`)
        ec.message.clearErrors()
        ec.message.popErrors()
        keptCount++
    }
}

const cf = ec.entity.conditionFactory
accountList = []
const ensured = ec.service.sync().name('org.moqui.impl.EmailClientServices.ensure#InternalAccount').call()
if (ec.message.hasError()) return
internalEmailAccountId = ensured.emailAccountId
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
const mailIds = access.accountList.filter((account) => !account.isInternal).map((account) => account.emailAccountId)
const KIND_ORDER = ['EfkInbox', 'EfkDrafts', 'EfkSent', 'EfkArchive', 'EfkJunk', 'EfkTrash', 'EfkOther']
const foldersByAccount = {}, labelsByAccount = {}, identitiesByAccount = {}, folderUnread = {}
if (mailIds.length) {
    for (const folder of ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', 'in', mailIds).list()) {
        (foldersByAccount[folder.emailAccountId] ||= []).push({emailFolderId: folder.emailFolderId, folderName: folder.folderName ?? null,
            folderPath: folder.folderPath ?? null, parentFolderId: folder.parentFolderId ?? null,
            folderKindEnumId: folder.folderKindEnumId || 'EfkOther', sequenceNum: folder.sequenceNum ?? null,
            unreadCount: 0, totalCount: folder.totalCount ?? null})
    }
    for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailAccountId', 'in', mailIds)
            .orderBy('sequenceNum,labelName').list()) {
        (labelsByAccount[label.emailAccountId] ||= []).push({emailLabelId: label.emailLabelId, labelName: label.labelName ?? null,
            color: label.color ?? null, sequenceNum: label.sequenceNum ?? null})
    }
    for (const identity of ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', 'in', mailIds)
            .orderBy('emailIdentityId').list()) {
        (identitiesByAccount[identity.emailAccountId] ||= []).push({emailIdentityId: identity.emailIdentityId,
            emailAddress: identity.emailAddress ?? null, displayName: identity.displayName ?? null,
            replyToAddress: identity.replyToAddress ?? null, signatureHtml: identity.signatureHtml ?? null,
            signaturePlacementEnumId: identity.signaturePlacementEnumId || 'EspBelowQuote',
            useForReplies: identity.useForReplies !== 'N', isDefault: identity.isDefault === 'Y'})
    }
    // the unread messages by folder, those of an Inbox not snoozed or archived
    const now = ec.user.nowTimestamp
    const inboxIds = new Set(Object.values(foldersByAccount).flat().filter((folder) => folder.folderKindEnumId === 'EfkInbox')
            .map((folder) => folder.emailFolderId))
    for (const row of ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', 'in', mailIds)
            .condition(cf.makeCondition('isRead', 'not-equals', 'Y', true)).condition('emailFolderId', 'not-equals', null)
            .selectField('emailFolderId').selectField('snoozedThruDate').selectField('archivedDate').list()) {
        if (inboxIds.has(row.emailFolderId)) {
            if (row.archivedDate != null) continue
            if (row.snoozedThruDate != null && Number(row.snoozedThruDate) > Number(now)) continue
        }
        folderUnread[row.emailFolderId] = (folderUnread[row.emailFolderId] || 0) + 1
    }
}
for (const account of access.accountList) {
    const item = Object.assign({}, account)
    if (account.isInternal) {
        Object.assign(item, {unreadCount: null, draftCount: 0, outboxCount: 0, outboxErrorCount: 0,
            folderList: [], labelList: [], identityList: []})
        accountList.push(item)
        continue
    }
    const folders = (foldersByAccount[account.emailAccountId] || [])
    for (const folder of folders) folder.unreadCount = folderUnread[folder.emailFolderId] || 0
    folders.sort((left, right) => (KIND_ORDER.indexOf(left.folderKindEnumId) - KIND_ORDER.indexOf(right.folderKindEnumId)) ||
            ((left.sequenceNum ?? 999999) - (right.sequenceNum ?? 999999)) || String(left.folderName).localeCompare(String(right.folderName)))
    const messages = () => ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', account.emailAccountId)
    item.unreadCount = folders.filter((folder) => folder.folderKindEnumId === 'EfkInbox').reduce((sum, folder) => sum + folder.unreadCount, 0)
    item.draftCount = messages().condition('statusId', 'ES_DRAFT').count()
    item.outboxCount = messages().condition('statusId', 'in', ['ES_SCHEDULED', 'ES_READY']).count()
    item.outboxErrorCount = messages().condition('statusId', 'ES_READY').condition('sendError', 'not-equals', null).count()
    item.folderList = folders
    item.labelList = labelsByAccount[account.emailAccountId] || []
    item.identityList = account.canSend ? (identitiesByAccount[account.emailAccountId] || []) : []
    accountList.push(item)
}

if (!['EapRead', 'EapSend', 'EapManage'].includes(permissionEnumId)) { ec.message.addError(`Unknown permission ${permissionEnumId}`); return }
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not share email account ${emailAccountId}`); return }
if (access.account.isInternal) { ec.message.addError('The Internal account is not shared'); return }
if (userId === access.account.ownerUserId) { ec.message.addError(`User ${userId} owns email account ${emailAccountId}`); return }
if (ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().count() === 0) {
    ec.message.addError(`User ${userId} not found`); return }
const current = ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', emailAccountId)
        .condition('userId', userId).conditionDate('fromDate', 'thruDate', null).list()
if (current.length) {
    for (const row of current) { row.set('permissionEnumId', permissionEnumId); row.update() }
    fromDate = current[0].fromDate
    return
}
const row = ec.entity.makeValue('moqui.basic.email.EmailAccountUser')
row.setFields({emailAccountId: emailAccountId, userId: userId, fromDate: ec.user.nowTimestamp,
    permissionEnumId: permissionEnumId}, false, null, null)
row.create()
fromDate = row.fromDate

removedCount = 0
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3 && userId !== ec.user.userId) { ec.message.addError(`You may not change who shares email account ${emailAccountId}`); return }
removedCount = ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', emailAccountId)
        .condition('userId', userId).conditionDate('fromDate', 'thruDate', null).updateAll({thruDate: ec.user.nowTimestamp})

success = false
stepList = []
folderList = []
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not test email account ${emailAccountId}`); return }
if (access.account.isInternal) { ec.message.addError('The Internal account has no server'); return }
if (!access.account.emailServerId) { ec.message.addError(`Email account ${emailAccountId} has no server`); return }
const result = ec.service.sync().name('org.moqui.impl.EmailServices.test#EmailServer').parameters({
    emailServerId: access.account.emailServerId, testSmtp: testSmtp, testStore: testStore}).disableAuthz().call()
if (ec.message.hasError()) return
success = result.success === true
stepList = result.stepList || []
folderList = result.folderList || []
if (success && ['EasAuthFailed', 'EasError'].includes(access.account.statusId)) {
    ec.service.sync().name('update#moqui.basic.email.EmailAccount').parameters({emailAccountId: emailAccountId,
        statusId: 'EasActive', lastSyncError: null}).disableAuthz().call()
}

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not add folders to email account ${emailAccountId}`); return }
if (access.account.isInternal) { ec.message.addError('The Internal account has no folders'); return }
folderName = String(folderName).trim()
if (!folderName) { ec.message.addError('A folder needs a name'); return }
if (parentFolderId && ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', parentFolderId)
        .condition('emailAccountId', emailAccountId).count() === 0) { ec.message.addError(`Email folder ${parentFolderId} not found`); return }
const siblings = ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', emailAccountId)
        .condition('parentFolderId', parentFolderId || null).list()
if (siblings.some((folder) => String(folder.folderName || '').toLowerCase() === folderName.toLowerCase())) {
    ec.message.addError(`There is a folder ${folderName} already`); return }
const folder = ec.entity.makeValue('moqui.basic.email.EmailFolder')
folder.setSequencedIdPrimary()
folder.setFields({emailAccountId: emailAccountId, folderName: folderName, parentFolderId: parentFolderId || null,
    folderKindEnumId: 'EfkOther', subscribed: 'Y', sequenceNum: sequenceNum}, false, null, null)
folder.create()
emailFolderId = folder.emailFolderId
