const cf = ec.entity.conditionFactory
const MESSAGE = 'moqui.basic.email.EmailMessage'
const VIEWS = ['inbox', 'flagged', 'snoozed', 'scheduled', 'outbox', 'drafts', 'sent', 'archive', 'junk', 'trash', 'all', 'folder', 'label']
const LIST_FIELDS = ['emailMessageId', 'rootEmailMessageId', 'parentEmailMessageId', 'emailAccountId', 'emailFolderId',
    'statusId', 'subject', 'snippet', 'fromAddress', 'fromName', 'toAddresses', 'ccAddresses', 'messageDate', 'isRead',
    'isFlagged', 'isAnswered', 'hasAttachment', 'snoozedThruDate', 'scheduledSendDate', 'archivedDate', 'sendError', 'messageSize']
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const splitAddresses = (text) => {
    const out = []
    if (!text) return out
    let current = '', quote = false, angle = 0
    for (const ch of String(text)) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if (ch === ',' && !quote && angle === 0) { if (current.trim()) out.push(current.trim()); current = ''; continue }
        current += ch
    }
    if (current.trim()) out.push(current.trim())
    return out.map((entry) => {
        const match = /^(.*)<([^>]+)>\s*$/.exec(entry)
        if (!match) return {address: entry, name: null}
        const name = match[1].trim().replace(/^"(.*)"$/, '$1').trim()
        return {address: match[2].trim(), name: name || null}
    })
}
threadList = []
hasMore = false
nextBeforeDate = null
if (!view) view = emailFolderId ? 'folder' : (emailLabelId ? 'label' : 'inbox')
if (!VIEWS.includes(view)) { ec.message.addError(`Unknown view ${view}: ${VIEWS.join(', ')}`); return }
if (view === 'folder' && !emailFolderId) { ec.message.addError('The folder view needs an emailFolderId'); return }
if (view === 'label' && !emailLabelId) { ec.message.addError('The label view needs an emailLabelId'); return }
if (!(pageSize > 0)) pageSize = 50

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
let accountIds = access.accountList.filter((account) => !account.isInternal).map((account) => account.emailAccountId)
const wanted = [].concat(emailAccountId ? [emailAccountId] : [], emailAccountIdList || [])
if (wanted.length) {
    for (const id of wanted) if (!access.accessMap[id]) { ec.message.addError(`Email account ${id} not found`); return }
    accountIds = accountIds.filter((id) => wanted.includes(id))
}
if (accountIds.length === 0) return

const folderKind = {}
const byKind = {EfkInbox: [], EfkDrafts: [], EfkSent: [], EfkArchive: [], EfkJunk: [], EfkTrash: [], EfkOther: []}
for (const folder of ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', 'in', accountIds)
        .selectField('emailFolderId').selectField('folderKindEnumId').list()) {
    const kind = folder.folderKindEnumId || 'EfkOther'
    folderKind[folder.emailFolderId] = kind
    ;(byKind[kind] ||= []).push(folder.emailFolderId)
}
if (emailFolderId && !folderKind[emailFolderId]) { ec.message.addError(`Email folder ${emailFolderId} not found`); return }
let labeledIds = null
if (view === 'label') {
    const label = ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', emailLabelId).one()
    if (label == null || !accountIds.includes(label.emailAccountId)) { ec.message.addError(`Email label ${emailLabelId} not found`); return }
    labeledIds = Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailLabelId', emailLabelId)
            .selectField('emailMessageId').list()).map((row) => row.emailMessageId)
    if (labeledIds.length === 0) return
}
const now = ec.user.nowTimestamp
const nowMillis = toMillis(now)
const trashJunk = byKind.EfkTrash.concat(byKind.EfkJunk)
const inTrashView = view === 'trash' || view === 'junk' || (view === 'folder' && trashJunk.includes(emailFolderId))
const notSnoozed = () => cf.makeCondition([cf.makeCondition('snoozedThruDate', 'equals', null),
    cf.makeCondition('snoozedThruDate', 'less-equals', now)], 'or')
const notTrashJunk = () => trashJunk.length ? cf.makeCondition('emailFolderId', 'not-in', trashJunk, true) : null
const inFolders = (ids) => ids.length ? cf.makeCondition('emailFolderId', 'in', ids) : null
// the conditions of the view and the filters; null when the view can have no message
const viewConditions = () => {
    const list = []
    const add = (condition) => { if (condition != null) list.push(condition) }
    switch (view) {
        case 'inbox':
            if (!byKind.EfkInbox.length) return null
            add(inFolders(byKind.EfkInbox)); add(cf.makeCondition('archivedDate', 'equals', null)); add(notSnoozed()); break
        case 'flagged': add(cf.makeCondition('isFlagged', 'equals', 'Y')); add(notTrashJunk()); break
        case 'snoozed': add(cf.makeCondition('snoozedThruDate', 'greater', now)); add(notTrashJunk()); break
        case 'scheduled': add(cf.makeCondition('statusId', 'equals', 'ES_SCHEDULED')); break
        case 'outbox': add(cf.makeCondition('statusId', 'in', ['ES_SCHEDULED', 'ES_READY'])); break
        case 'drafts': add(cf.makeCondition('statusId', 'equals', 'ES_DRAFT')); add(notTrashJunk()); break
        case 'sent': if (!byKind.EfkSent.length) return null; add(inFolders(byKind.EfkSent)); break
        case 'archive': {
            const either = [cf.makeCondition('archivedDate', 'not-equals', null)]
            if (byKind.EfkArchive.length) either.push(inFolders(byKind.EfkArchive))
            add(cf.makeCondition(either, 'or')); add(notTrashJunk()); break
        }
        case 'junk': if (!byKind.EfkJunk.length) return null; add(inFolders(byKind.EfkJunk)); break
        case 'trash': if (!byKind.EfkTrash.length) return null; add(inFolders(byKind.EfkTrash)); break
        case 'all': add(notTrashJunk()); break
        case 'folder':
            add(cf.makeCondition('emailFolderId', 'equals', emailFolderId))
            if (folderKind[emailFolderId] === 'EfkInbox') { add(cf.makeCondition('archivedDate', 'equals', null)); add(notSnoozed()) }
            break
        case 'label': add(cf.makeCondition('emailMessageId', 'in', labeledIds)); add(notTrashJunk()); break
    }
    if (unreadOnly) add(cf.makeCondition('isRead', 'not-equals', 'Y', true))
    if (flaggedOnly) add(cf.makeCondition('isFlagged', 'equals', 'Y'))
    if (hasAttachment === true) add(cf.makeCondition('hasAttachment', 'equals', 'Y'))
    if (hasAttachment === false) add(cf.makeCondition('hasAttachment', 'not-equals', 'Y', true))
    const like = (field, text) => cf.makeCondition(field, 'like', `%${text}%`, false, true)
    if (searchText) add(cf.makeCondition(['subject', 'body', 'bodyText', 'fromAddress', 'fromName', 'toAddresses', 'ccAddresses']
            .map((field) => like(field, searchText)), 'or'))
    if (fromAddress) add(cf.makeCondition([like('fromAddress', fromAddress), like('fromName', fromAddress)], 'or'))
    if (toAddress) add(cf.makeCondition([like('toAddresses', toAddress), like('ccAddresses', toAddress)], 'or'))
    if (subject) add(like('subject', subject))
    if (fromDate != null) add(cf.makeCondition('messageDate', 'greater-equals', fromDate))
    if (thruDate != null) add(cf.makeCondition('messageDate', 'less', thruDate))
    if (minSize != null) add(cf.makeCondition('messageSize', 'greater-equals', minSize))
    if (maxSize != null) add(cf.makeCondition('messageSize', 'less-equals', maxSize))
    return list
}
const conditions = viewConditions()
if (conditions == null) return
const makeFind = () => {
    let find = ec.entity.find(MESSAGE).condition('emailAccountId', 'in', accountIds)
            .condition(cf.makeCondition('messageDate', 'not-equals', null))
    for (const condition of conditions) find = find.condition(condition)
    return find
}

// the labels of the messages shown
const labelsOf = (messageIds) => {
    const out = {}
    if (!messageIds.length) return out
    const joins = Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', 'in', messageIds).list())
    const labelIds = Array.from(new Set(joins.map((row) => row.emailLabelId)))
    const labels = {}
    if (labelIds.length) for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', 'in', labelIds).list())
        labels[label.emailLabelId] = {emailLabelId: label.emailLabelId, labelName: label.labelName ?? null, color: label.color ?? null}
    for (const row of joins) if (labels[row.emailLabelId]) (out[row.emailMessageId] ||= []).push(labels[row.emailLabelId])
    return out
}
const archiveFolders = new Set(byKind.EfkArchive)
const summarize = (threadId, messages, viewMessageId, sortDate, labelMap) => {
    const first = messages[0]
    const last = messages[messages.length - 1]
    const shown = messages.find((message) => message.emailMessageId === viewMessageId) || last
    const root = messages.find((message) => message.emailMessageId === threadId) || first
    const participants = []
    const seenAddresses = new Set()
    for (const message of messages) {
        for (const entry of [].concat(splitAddresses(message.fromName ? `"${message.fromName}" <${message.fromAddress}>` : message.fromAddress),
                splitAddresses(message.toAddresses), splitAddresses(message.ccAddresses))) {
            const key = String(entry.address).toLowerCase()
            if (!entry.address || seenAddresses.has(key)) continue
            seenAddresses.add(key)
            participants.push(entry)
        }
    }
    const labelList = []
    const labelSeen = new Set()
    for (const message of messages) for (const label of (labelMap[message.emailMessageId] || [])) {
        if (labelSeen.has(label.emailLabelId)) continue
        labelSeen.add(label.emailLabelId)
        labelList.push(label)
    }
    const snoozes = messages.map((message) => toMillis(message.snoozedThruDate)).filter((millis) => millis != null && millis > nowMillis)
    const unreadCount = messages.filter((message) => message.isRead !== 'Y').length
    return {store: 'email', threadId: threadId, rootEmailMessageId: threadId, lastEmailMessageId: last.emailMessageId,
        emailMessageId: shown.emailMessageId, emailAccountId: shown.emailAccountId, emailFolderId: shown.emailFolderId ?? null,
        folderKindEnumId: shown.emailFolderId ? (folderKind[shown.emailFolderId] || null) : null, statusId: shown.statusId ?? null,
        subject: root.subject ?? null, snippet: last.snippet ?? null, sortDate: sortDate,
        lastDate: toMillis(last.messageDate), firstDate: toMillis(first.messageDate),
        messageCount: messages.length, replyCount: messages.length - 1, unreadCount: unreadCount, isUnread: unreadCount > 0,
        isFlagged: messages.some((message) => message.isFlagged === 'Y'),
        isArchived: messages.every((message) => message.archivedDate != null || archiveFolders.has(message.emailFolderId)),
        snoozedThruDate: snoozes.length ? Math.max.apply(null, snoozes) : null,
        scheduledSendDate: toMillis(shown.scheduledSendDate), hasAttachment: messages.some((message) => message.hasAttachment === 'Y'),
        draftCount: messages.filter((message) => message.statusId === 'ES_DRAFT').length,
        fromAddress: last.fromAddress ?? null, fromName: last.fromName ?? null, participantList: participants,
        participantAddressList: participants.map((entry) => entry.address), labelList: labelList, sendError: shown.sendError ?? null,
        fromPartyId: null, participantPartyIdList: [], contactListId: null, contactListName: null, isClosed: false}
}
const plain = (row) => {
    const out = {}
    for (const field of LIST_FIELDS) out[field] = row[field] ?? null
    return out
}
const beforeMillis = toMillis(beforeDate)
const withCursor = (find) => beforeMillis == null ? find : find.condition(cf.makeCondition('messageDate', 'less', new Date(beforeMillis)))

if (!threadMode) {
    let find = withCursor(makeFind())
    for (const field of LIST_FIELDS) find = find.selectField(field)
    const rows = Array.from(find.orderBy('-messageDate').orderBy('-emailMessageId').limit(pageSize + 1).list()).map(plain)
    hasMore = rows.length > pageSize
    const page = rows.slice(0, pageSize)
    const labelMap = labelsOf(page.map((row) => row.emailMessageId))
    threadList = page.map((row) => summarize(row.rootEmailMessageId || row.emailMessageId, [row], row.emailMessageId,
            toMillis(row.messageDate), labelMap))
    if (hasMore) nextBeforeDate = threadList[threadList.length - 1].sortDate
    return
}

// threads: scan the view's messages newest first; a thread comes at its newest one
const chunkSize = Math.max(pageSize * 2, 50)
const seen = new Set()
const accepted = []
let offset = 0
while (accepted.length <= pageSize) {
    const rows = Array.from(withCursor(makeFind()).selectField('emailMessageId').selectField('rootEmailMessageId')
            .selectField('messageDate').orderBy('-messageDate').orderBy('-emailMessageId').offset(offset).limit(chunkSize).list())
    offset += rows.length
    const fresh = []
    for (const row of rows) {
        const threadId = row.rootEmailMessageId || row.emailMessageId
        if (seen.has(threadId)) continue
        seen.add(threadId)
        fresh.push({threadId: threadId, viewMessageId: row.emailMessageId, sortDate: toMillis(row.messageDate)})
    }
    if (fresh.length) {
        const ids = fresh.map((candidate) => candidate.threadId)
        const inThreads = () => cf.makeCondition([cf.makeCondition('emailMessageId', 'in', ids), cf.makeCondition('rootEmailMessageId', 'in', ids)], 'or')
        // a thread with a message in the view at or after the cursor was on an earlier page
        let shownBefore = new Set()
        if (beforeMillis != null) {
            shownBefore = new Set(Array.from(makeFind().condition(inThreads()).condition(cf.makeCondition('messageDate', 'greater-equals',
                new Date(beforeMillis))).selectField('emailMessageId').selectField('rootEmailMessageId').list())
                .map((row) => row.rootEmailMessageId || row.emailMessageId))
        }
        const candidates = fresh.filter((candidate) => !shownBefore.has(candidate.threadId))
        if (candidates.length) {
            let find = ec.entity.find(MESSAGE).condition('emailAccountId', 'in', accountIds).condition(inThreads())
                    .condition(cf.makeCondition('messageDate', 'not-equals', null))
            if (inTrashView) find = find.condition(cf.makeCondition('emailFolderId', 'in', trashJunk))
            else if (trashJunk.length) find = find.condition(notTrashJunk())
            for (const field of LIST_FIELDS) find = find.selectField(field)
            const byThread = {}
            for (const row of find.orderBy('messageDate').orderBy('emailMessageId').list()) {
                (byThread[row.rootEmailMessageId || row.emailMessageId] ||= []).push(plain(row))
            }
            const labelMap = labelsOf(Object.values(byThread).flat().map((row) => row.emailMessageId))
            for (const candidate of candidates) {
                const messages = byThread[candidate.threadId]
                if (!messages || !messages.length) continue
                accepted.push(summarize(candidate.threadId, messages, candidate.viewMessageId, candidate.sortDate, labelMap))
                if (accepted.length > pageSize) break
            }
        }
    }
    if (rows.length < chunkSize) break
}
hasMore = accepted.length > pageSize
threadList = accepted.slice(0, pageSize)
if (hasMore) nextBeforeDate = threadList[threadList.length - 1].sortDate

const cf = ec.entity.conditionFactory
const MESSAGE = 'moqui.basic.email.EmailMessage'
const DATE_FIELDS = ['sentDate', 'receivedDate', 'messageDate', 'snoozedThruDate', 'scheduledSendDate', 'archivedDate']
const FIELDS = ['emailMessageId', 'rootEmailMessageId', 'parentEmailMessageId', 'emailAccountId', 'emailFolderId',
    'emailIdentityId', 'statusId', 'emailTypeEnumId', 'messageId', 'subject', 'body', 'bodyText', 'contentType', 'fromAddress',
    'fromName', 'toAddresses', 'ccAddresses', 'bccAddresses', 'inReplyTo', 'referencesHeader', 'isRead', 'isFlagged',
