let find = ec.entity.find(MESSAGE).condition('emailAccountId', 'in', readable).condition(cf.makeCondition([
    cf.makeCondition('emailMessageId', 'equals', rootEmailMessageId), cf.makeCondition('rootEmailMessageId', 'equals', rootEmailMessageId)], 'or'))
for (const field of FIELDS.concat(includeHeaders ? ['headersString'] : [])) find = find.selectField(field)
const rows = Array.from(find.orderBy('messageDate').orderBy('emailMessageId').list())
if (rows.length === 0) { ec.message.addError(`Email message ${wanted} not found`); return }
const ids = rows.map((row) => row.emailMessageId)
const folderIds = Array.from(new Set(rows.map((row) => row.emailFolderId).filter((id) => id)))
const folderKind = {}
if (folderIds.length) for (const folder of ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', 'in', folderIds).list())
    folderKind[folder.emailFolderId] = folder.folderKindEnumId || 'EfkOther'
const attachments = {}
for (const row of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', 'in', ids)
        .orderBy('emailMessageAttachmentId').list()) {
    (attachments[row.emailMessageId] ||= []).push({emailMessageAttachmentId: row.emailMessageAttachmentId,
        attachmentLocation: row.attachmentLocation ?? null, fileName: row.fileName ?? null, fileSize: row.fileSize ?? null,
        contentType: row.contentType ?? null, contentId: row.contentId ?? null, isInline: row.isInline === 'Y'})
}
const joins = Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', 'in', ids).list())
const labelIds = Array.from(new Set(joins.map((row) => row.emailLabelId)))
const labels = {}
if (labelIds.length) for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', 'in', labelIds).list())
    labels[label.emailLabelId] = {emailLabelId: label.emailLabelId, labelName: label.labelName ?? null, color: label.color ?? null}
const labelsOf = {}
for (const row of joins) if (labels[row.emailLabelId]) (labelsOf[row.emailMessageId] ||= []).push(labels[row.emailLabelId])
for (const row of rows) {
