    for (const field of DATE_FIELDS) message[field] = toMillis(row[field])
    message.folderKindEnumId = row.emailFolderId ? (folderKind[row.emailFolderId] || null) : null
    message.attachmentList = attachments[row.emailMessageId] || []
    message.labelList = labelsOf[row.emailMessageId] || []
    message.canSend = (access.accessMap[row.emailAccountId] || 0) >= 2
    message.isUnread = row.isRead !== 'Y'
    if (message.isUnread) unreadCount++
    messageList.push(message)
}
const root = messageList.find((message) => message.emailMessageId === rootEmailMessageId) || messageList[0]
subject = root.subject
const last = messageList[messageList.length - 1]
emailAccountId = last.emailAccountId
canSend = last.canSend

const cf = ec.entity.conditionFactory
const MESSAGE = 'moqui.basic.email.EmailMessage'
targetList = []
accountMap = {}
const ids = Array.from(new Set([].concat(emailMessageId ? [emailMessageId] : [], emailMessageIdList || []).filter((id) => id)))
if (!ids.length && !rootEmailMessageId) { ec.message.addError('An emailMessageId, emailMessageIdList or rootEmailMessageId is required'); return }
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
