const readable = access.accountList.filter((account) => !account.isInternal).map((account) => account.emailAccountId)
const missing = rootEmailMessageId || ids[0]
if (readable.length === 0) { ec.message.addError(`Email message ${missing} not found`); return }
const select = (find) => find.selectField('emailMessageId').selectField('rootEmailMessageId').selectField('emailAccountId')
        .selectField('emailFolderId').selectField('statusId')
const rows = []
if (rootEmailMessageId) {
    const thread = Array.from(select(ec.entity.find(MESSAGE).condition('emailAccountId', 'in', readable).condition(cf.makeCondition([
        cf.makeCondition('emailMessageId', 'equals', rootEmailMessageId), cf.makeCondition('rootEmailMessageId', 'equals', rootEmailMessageId)], 'or'))).list())
    if (thread.length === 0) { ec.message.addError(`Email message ${rootEmailMessageId} not found`); return }
    rows.push(...thread)
}
if (ids.length) {
    const found = Array.from(select(ec.entity.find(MESSAGE).condition('emailMessageId', 'in', ids).condition('emailAccountId', 'in', readable)).list())
    const foundIds = new Set(found.map((row) => row.emailMessageId))
    for (const id of ids) if (!foundIds.has(id)) { ec.message.addError(`Email message ${id} not found`); return }
    for (const row of found) if (!rows.some((other) => other.emailMessageId === row.emailMessageId)) rows.push(row)
}
for (const row of rows) {
    if ((access.accessMap[row.emailAccountId] || 0) < minLevel) {
        ec.message.addError(`You may not change the mail of email account ${row.emailAccountId}`); return }
}
const accountIds = Array.from(new Set(rows.map((row) => row.emailAccountId)))
const folderKind = {}
for (const account of access.accountList) if (accountIds.includes(account.emailAccountId))
    accountMap[account.emailAccountId] = {emailServerId: account.emailServerId, folderIdByKind: {}}
for (const folder of ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', 'in', accountIds).orderBy('sequenceNum,emailFolderId').list()) {
    const kind = folder.folderKindEnumId || 'EfkOther'
    folderKind[folder.emailFolderId] = kind
    const byKind = accountMap[folder.emailAccountId].folderIdByKind
    if (!byKind[kind]) byKind[kind] = folder.emailFolderId
}
targetList = rows.map((row) => ({emailMessageId: row.emailMessageId, rootEmailMessageId: row.rootEmailMessageId ?? null,
    emailAccountId: row.emailAccountId, emailFolderId: row.emailFolderId ?? null, statusId: row.statusId ?? null,
    folderKindEnumId: row.emailFolderId ? (folderKind[row.emailFolderId] || null) : null}))

const ids = Array.from(new Set((emailAccountIdList || []).filter((id) => id)))
if (!ids.length) return
const users = new Set()
for (const account of ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', 'in', ids)
        .selectField('ownerUserId').list()) if (account.ownerUserId) users.add(account.ownerUserId)
for (const row of ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', 'in', ids)
        .conditionDate('fromDate', 'thruDate', null).selectField('userId').list()) users.add(row.userId)
if (!users.size) return
ec.message.pushErrors()
ec.service.sync().name('org.moqui.impl.ShellServices.publish#ShellCounts').parameter('userIdList', Array.from(users)).call()
if (ec.message.hasError()) ec.logger.warn(`Could not publish the shell counts of email accounts ${ids.join(', ')}: ${ec.message.errorsString}`)
ec.message.clearErrors()
ec.message.popErrors()

updatedCount = 0
const resolved = ec.service.sync().name('org.moqui.impl.EmailClientServices.resolve#MessageTargets').parameters({
    emailMessageId: emailMessageId, emailMessageIdList: emailMessageIdList, rootEmailMessageId: rootEmailMessageId,
    minLevel: flagged != null || answered != null ? 2 : 1}).call()
emailMessageIdList = []
if (ec.message.hasError()) return
const fields = {}
if (read != null) fields.isRead = read ? 'Y' : 'N'
if (flagged != null) fields.isFlagged = flagged ? 'Y' : 'N'
if (answered != null) fields.isAnswered = answered ? 'Y' : 'N'
if (!Object.keys(fields).length) return
const byAccount = {}
for (const target of resolved.targetList) {
    const row = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', target.emailMessageId).one()
    if (Object.keys(fields).every((name) => (row[name] || 'N') === fields[name])) continue
    row.setFields(fields, true, null, null)
    row.update()
    updatedCount++
    emailMessageIdList.push(target.emailMessageId)
    ;(byAccount[target.emailAccountId] ||= []).push(target.emailMessageId)
}
for (const accountId of Object.keys(byAccount)) {
    if (resolved.accountMap[accountId]?.emailServerId) ec.service.sync().name('org.moqui.impl.EmailClientServices.push#RemoteChanges')
            .parameters({emailAccountId: accountId, changeType: 'flags', emailMessageIdList: byAccount[accountId], flagMap: fields})
            .disableAuthz().call()
}
if (read != null && updatedCount) ec.service.sync().name('org.moqui.impl.EmailClientServices.publish#AccountCounts')
        .parameter('emailAccountIdList', Object.keys(byAccount)).disableAuthz().call()

updatedCount = 0
const folder = ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', emailFolderId).one()
const resolved = ec.service.sync().name('org.moqui.impl.EmailClientServices.resolve#MessageTargets').parameters({
    emailMessageId: emailMessageId, emailMessageIdList: emailMessageIdList, rootEmailMessageId: rootEmailMessageId, minLevel: 2}).call()
emailMessageIdList = []
if (ec.message.hasError()) return
if (folder == null || !resolved.targetList.every((target) => target.emailAccountId === folder.emailAccountId)) {
    ec.message.addError(`Email folder ${emailFolderId} not found in the account of these messages`); return }
for (const target of resolved.targetList) if (['ES_DRAFT', 'ES_SCHEDULED', 'ES_READY'].includes(target.statusId)) {
    ec.message.addError(`Email message ${target.emailMessageId} is a draft or in the Outbox and is not moved`); return }
const toArchive = folder.folderKindEnumId === 'EfkArchive'
const now = ec.user.nowTimestamp
const fromFolderMap = {}
for (const target of resolved.targetList) {
    if (target.emailFolderId === emailFolderId) continue
    const row = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', target.emailMessageId).one()
    row.set('emailFolderId', emailFolderId)
    row.set('archivedDate', toArchive ? (row.archivedDate || now) : null)
    row.update()
    fromFolderMap[target.emailMessageId] = target.emailFolderId
    emailMessageIdList.push(target.emailMessageId)
    updatedCount++
}
if (!updatedCount) return
if (resolved.accountMap[folder.emailAccountId]?.emailServerId) ec.service.sync().name('org.moqui.impl.EmailClientServices.push#RemoteChanges')
        .parameters({emailAccountId: folder.emailAccountId, changeType: 'move', emailMessageIdList: emailMessageIdList,
            emailFolderId: emailFolderId, fromFolderMap: fromFolderMap}).disableAuthz().call()
ec.service.sync().name('org.moqui.impl.EmailClientServices.publish#AccountCounts')
        .parameter('emailAccountIdList', [folder.emailAccountId]).disableAuthz().call()

updatedCount = 0
const resolved = ec.service.sync().name('org.moqui.impl.EmailClientServices.resolve#MessageTargets').parameters({
    emailMessageId: emailMessageId, emailMessageIdList: emailMessageIdList, rootEmailMessageId: rootEmailMessageId, minLevel: 2}).call()
emailMessageIdList = []
if (ec.message.hasError()) return
const adding = Array.from(new Set(addLabelIdList || []))
const removing = Array.from(new Set(removeLabelIdList || []))
const all = adding.concat(removing)
const labelAccount = {}
if (all.length) for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', 'in', all).list())
    labelAccount[label.emailLabelId] = label.emailAccountId
for (const id of all) if (!labelAccount[id]) { ec.message.addError(`Email label ${id} not found`); return }
for (const target of resolved.targetList) for (const id of all) if (labelAccount[id] !== target.emailAccountId) {
    ec.message.addError(`Email label ${id} is not of the account of email message ${target.emailMessageId}`); return }
const changed = new Set()
const byAccount = {}
for (const target of resolved.targetList) {
    const has = new Set(Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', target.emailMessageId)
            .list()).map((row) => row.emailLabelId))
    for (const id of adding) if (!has.has(id)) {
        const row = ec.entity.makeValue('moqui.basic.email.EmailMessageLabel')
        row.setFields({emailMessageId: target.emailMessageId, emailLabelId: id}, false, null, null)
        row.create()
        changed.add(target.emailMessageId)
    }
    for (const id of removing) if (has.has(id)) {
        ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', target.emailMessageId)
                .condition('emailLabelId', id).deleteAll()
        changed.add(target.emailMessageId)
    }
    if (changed.has(target.emailMessageId)) (byAccount[target.emailAccountId] ||= []).push(target.emailMessageId)
}
emailMessageIdList = Array.from(changed)
updatedCount = emailMessageIdList.length
for (const accountId of Object.keys(byAccount)) {
    if (resolved.accountMap[accountId]?.emailServerId) ec.service.sync().name('org.moqui.impl.EmailClientServices.push#RemoteChanges')
            .parameters({emailAccountId: accountId, changeType: 'labels', emailMessageIdList: byAccount[accountId]}).disableAuthz().call()
}

updatedCount = 0
if (!unsnooze && snoozedThruDate == null) { ec.message.addError('Snooze until when? A snoozedThruDate is required'); return }
if (!unsnooze && Number(new Date(Number(snoozedThruDate) || String(snoozedThruDate)).getTime()) <= Number(ec.user.nowTimestamp)) {
    ec.message.addError('Snooze until a time in the future'); return }
const resolved = ec.service.sync().name('org.moqui.impl.EmailClientServices.resolve#MessageTargets').parameters({
    emailMessageId: emailMessageId, emailMessageIdList: emailMessageIdList, rootEmailMessageId: rootEmailMessageId, minLevel: 2}).call()
emailMessageIdList = []
if (ec.message.hasError()) return
const accounts = new Set()
for (const target of resolved.targetList) {
    const row = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', target.emailMessageId).one()
    if (unsnooze && row.snoozedThruDate == null) continue
    row.set('snoozedThruDate', unsnooze ? null : snoozedThruDate)
    row.update()
    emailMessageIdList.push(target.emailMessageId)
    accounts.add(target.emailAccountId)
    updatedCount++
}
if (updatedCount) ec.service.sync().name('org.moqui.impl.EmailClientServices.publish#AccountCounts')
        .parameter('emailAccountIdList', Array.from(accounts)).disableAuthz().call()

updatedCount = 0
deletedCount = 0
const resolved = ec.service.sync().name('org.moqui.impl.EmailClientServices.resolve#MessageTargets').parameters({
    emailMessageId: emailMessageId, emailMessageIdList: emailMessageIdList, rootEmailMessageId: rootEmailMessageId, minLevel: 2}).call()
emailMessageIdList = []
if (ec.message.hasError()) return
for (const target of resolved.targetList) if (['ES_SCHEDULED', 'ES_READY'].includes(target.statusId)) {
    ec.message.addError(`Email message ${target.emailMessageId} is in the Outbox; cancel its send first`); return }
// a thread's messages outside the trash stay when it is deleted from the trash
const targets = deleteForever && rootEmailMessageId && !emailMessageId && !(emailMessageIdList || []).length
    ? resolved.targetList.filter((target) => target.folderKindEnumId === 'EfkTrash' || target.statusId === 'ES_DRAFT')
    : resolved.targetList
if (deleteForever) for (const target of targets) if (target.folderKindEnumId !== 'EfkTrash' && target.statusId !== 'ES_DRAFT') {
    ec.message.addError(`Email message ${target.emailMessageId} is not in the Trash; only messages there are deleted forever`); return }
const toDelete = targets.filter((target) => deleteForever || target.statusId === 'ES_DRAFT')
const toTrash = targets.filter((target) => !deleteForever && target.statusId !== 'ES_DRAFT' && target.folderKindEnumId !== 'EfkTrash')
for (const target of toTrash) if (!resolved.accountMap[target.emailAccountId]?.folderIdByKind?.EfkTrash) {
    ec.message.addError(`Email account ${target.emailAccountId} has no Trash folder`); return }
const accounts = new Set()
// each one deleted in its own transaction, so one a record refers to does not stop the rest; before any move
// here, so the transaction of this service holds no lock a delete waits on
const deletedByAccount = {}
for (const target of toDelete) {
    ec.message.pushErrors()
    ec.service.sync().name('org.moqui.impl.EmailClientServices.delete#LocalMessages').parameter('emailMessageIdList', [target.emailMessageId])
            .requireNewTransaction(true).disableAuthz().call()
    const failed = ec.message.hasError() ? ec.message.errorsString : null
    ec.message.clearErrors()
    if (failed != null) {
        ec.logger.warn(`Email message ${target.emailMessageId} is not deleted, a record refers to it; taking it out of its account: ${failed}`)
        ec.service.sync().name('org.moqui.impl.EmailClientServices.detach#LocalMessages').parameter('emailMessageIdList', [target.emailMessageId])
                .requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) ec.logger.log('error', `Could not take email message ${target.emailMessageId} out of its account: ${ec.message.errorsString}`)
        ec.message.clearErrors()
    }
    ec.message.popErrors()
    ;(deletedByAccount[target.emailAccountId] ||= []).push(target.emailMessageId)
    accounts.add(target.emailAccountId)
    emailMessageIdList.push(target.emailMessageId)
    deletedCount++
}
const fromFolders = {}
for (const target of toTrash) {
    const trashId = resolved.accountMap[target.emailAccountId].folderIdByKind.EfkTrash
    const row = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', target.emailMessageId).one()
    row.set('emailFolderId', trashId)
    row.update()
    ;(fromFolders[target.emailAccountId] ||= {})[target.emailMessageId] = target.emailFolderId
    accounts.add(target.emailAccountId)
    emailMessageIdList.push(target.emailMessageId)
    updatedCount++
}
for (const accountId of Object.keys(fromFolders)) {
    if (resolved.accountMap[accountId]?.emailServerId) ec.service.sync().name('org.moqui.impl.EmailClientServices.push#RemoteChanges')
            .parameters({emailAccountId: accountId, changeType: 'move', emailMessageIdList: Object.keys(fromFolders[accountId]),
                emailFolderId: resolved.accountMap[accountId].folderIdByKind.EfkTrash, fromFolderMap: fromFolders[accountId]}).disableAuthz().call()
}
for (const accountId of Object.keys(deletedByAccount)) {
    if (resolved.accountMap[accountId]?.emailServerId) ec.service.sync().name('org.moqui.impl.EmailClientServices.push#RemoteChanges')
            .parameters({emailAccountId: accountId, changeType: 'delete', emailMessageIdList: deletedByAccount[accountId]}).disableAuthz().call()
}
if (accounts.size) ec.service.sync().name('org.moqui.impl.EmailClientServices.publish#AccountCounts')
        .parameter('emailAccountIdList', Array.from(accounts)).disableAuthz().call()

const cf = ec.entity.conditionFactory
const MESSAGE = 'moqui.basic.email.EmailMessage'
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('delete#LocalMessages is internal'); return }
const ids = Array.from(new Set(emailMessageIdList.filter((id) => id)))
if (!ids.length) return
const going = new Set(ids)
const rows = Array.from(ec.entity.find(MESSAGE).condition('emailMessageId', 'in', ids)
        .selectField('emailMessageId').selectField('parentEmailMessageId').selectField('rootEmailMessageId').list())
const parentOf = {}
for (const row of rows) parentOf[row.emailMessageId] = row.parentEmailMessageId ?? null
const survivingParent = (id) => {
    let parent = parentOf[id] ?? null
    const guard = new Set()
    while (parent && going.has(parent) && !guard.has(parent)) { guard.add(parent); parent = parentOf[parent] ?? null }
    return parent
}
// replies that stay: their parent is the nearest one that stays
for (const child of ec.entity.find(MESSAGE).condition('parentEmailMessageId', 'in', ids).condition('emailMessageId', 'not-in', ids).list()) {
    child.set('parentEmailMessageId', survivingParent(child.parentEmailMessageId))
    child.update()
}
// threads that stay: their oldest remaining message is the root
const rootIds = ids.filter((id) => rows.some((row) => row.emailMessageId === id && !row.rootEmailMessageId))
for (const rootId of rootIds) {
    const members = Array.from(ec.entity.find(MESSAGE).condition('rootEmailMessageId', rootId).condition('emailMessageId', 'not-in', ids)
            .orderBy('messageDate').orderBy('emailMessageId').list())
    if (!members.length) continue
    const newRoot = members[0]
    newRoot.set('rootEmailMessageId', null)
    newRoot.update()
    for (const member of members.slice(1)) { member.set('rootEmailMessageId', newRoot.emailMessageId); member.update() }
}
for (const attachment of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', 'in', ids).list()) {
    const location = attachment.attachmentLocation
    if (location && String(location).startsWith('dbresource://email/')) {
        try { ec.resource.getLocationReference(location).delete() }
        catch (err) { ec.logger.warn(`Could not delete the attachment file ${location}: ${err}`) }
    }
}
ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', 'in', ids).deleteAll()
ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', 'in', ids).deleteAll()
// the thread's own references among the ones going, then the rows
ec.entity.find(MESSAGE).condition('emailMessageId', 'in', ids).updateAll({rootEmailMessageId: null, parentEmailMessageId: null})
ec.entity.find(MESSAGE).condition('emailMessageId', 'in', ids).deleteAll()

if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('detach#LocalMessages is internal'); return }
const ids = emailMessageIdList.filter((id) => id)
if (!ids.length) return
ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', 'in', ids).deleteAll()
ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', 'in', ids)
        .updateAll({emailAccountId: null, emailFolderId: null, emailIdentityId: null, emailServerId: null})

updatedCount = 0
const resolved = ec.service.sync().name('org.moqui.impl.EmailClientServices.resolve#MessageTargets').parameters({
    emailMessageId: emailMessageId, emailMessageIdList: emailMessageIdList, rootEmailMessageId: rootEmailMessageId, minLevel: 2}).call()
emailMessageIdList = []
if (ec.message.hasError()) return
const now = ec.user.nowTimestamp
const moves = {}
for (const target of resolved.targetList) {
    if (['ES_DRAFT', 'ES_SCHEDULED', 'ES_READY'].includes(target.statusId)) continue
    const byKind = resolved.accountMap[target.emailAccountId]?.folderIdByKind || {}
    const row = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', target.emailMessageId).one()
    let toFolder = null
    if (unarchive) {
        if (target.folderKindEnumId !== 'EfkArchive' && row.archivedDate == null) continue
        if (target.folderKindEnumId === 'EfkArchive') toFolder = byKind.EfkInbox
        row.set('archivedDate', null)
    } else {
        if (!['EfkInbox', 'EfkOther'].includes(target.folderKindEnumId)) continue
        toFolder = byKind.EfkArchive || null
        row.set('archivedDate', row.archivedDate || now)
    }
    if (toFolder && toFolder !== target.emailFolderId) {
        row.set('emailFolderId', toFolder)
        const move = (moves[target.emailAccountId] ||= {toFolder: toFolder, fromFolderMap: {}})
        move.fromFolderMap[target.emailMessageId] = target.emailFolderId
    }
    row.update()
    emailMessageIdList.push(target.emailMessageId)
    updatedCount++
}
for (const accountId of Object.keys(moves)) {
    if (resolved.accountMap[accountId]?.emailServerId) ec.service.sync().name('org.moqui.impl.EmailClientServices.push#RemoteChanges')
            .parameters({emailAccountId: accountId, changeType: 'move', emailMessageIdList: Object.keys(moves[accountId].fromFolderMap),
                emailFolderId: moves[accountId].toFolder, fromFolderMap: moves[accountId].fromFolderMap}).disableAuthz().call()
}
if (updatedCount) ec.service.sync().name('org.moqui.impl.EmailClientServices.publish#AccountCounts')
        .parameter('emailAccountIdList', Array.from(new Set(resolved.targetList.map((target) => target.emailAccountId)))).disableAuthz().call()

const MESSAGE = 'moqui.basic.email.EmailMessage'
const textOf = (html) => html ? String(html).replace(/<(style|script)[^>]*>[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]*>/g, ' ')
        .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
        .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim() : ''
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
let draft = null
if (emailMessageId) {
    draft = ec.entity.find(MESSAGE).condition('emailMessageId', emailMessageId).forUpdate(true).one()
    if (draft == null || !access.accessMap[draft.emailAccountId]) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    if (access.accessMap[draft.emailAccountId] < 2) { ec.message.addError(`You may not change the mail of email account ${draft.emailAccountId}`); return }
    if (!(draft.statusId === 'ES_DRAFT' || (draft.statusId === 'ES_READY' && draft.sendError))) {
        ec.message.addError(`Email message ${emailMessageId} is not a draft`); return }
}
let identity = null
if (emailIdentityId) {
    identity = ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailIdentityId', emailIdentityId).one()
    if (identity == null || !access.accessMap[identity.emailAccountId]) { ec.message.addError(`Email identity ${emailIdentityId} not found`); return }
    if (emailAccountId && emailAccountId !== identity.emailAccountId) {
        ec.message.addError(`Email identity ${emailIdentityId} is not of email account ${emailAccountId}`); return }
    emailAccountId = identity.emailAccountId
}
if (!emailAccountId) emailAccountId = draft ? draft.emailAccountId : null
if (!emailAccountId) { ec.message.addError('A draft needs the account it is sent from'); return }
const account = access.accountList.find((candidate) => candidate.emailAccountId === emailAccountId)
if (account == null) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (account.isInternal) { ec.message.addError('An internal message is not an email draft; the app that keeps internal messages sends it'); return }
if (!account.canSend) { ec.message.addError(`You may not send from email account ${emailAccountId}`); return }
const accountChanged = draft != null && draft.emailAccountId !== emailAccountId
if (identity == null && (draft == null || accountChanged || (draft.emailIdentityId == null && emailIdentityId == null))) {
    const identities = Array.from(ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', emailAccountId)
            .orderBy('emailIdentityId').list())
    identity = identities.find((candidate) => candidate.isDefault === 'Y') || identities[0] || null
} else if (identity == null && draft?.emailIdentityId) {
    identity = ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailIdentityId', draft.emailIdentityId).one()
}
const drafts = ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', emailAccountId)
        .condition('folderKindEnumId', 'EfkDrafts').orderBy('sequenceNum,emailFolderId').limit(1).list()
const draftsFolderId = drafts.length ? drafts[0].emailFolderId : null
const fields = {statusId: 'ES_DRAFT', emailAccountId: emailAccountId, emailFolderId: draftsFolderId,
    emailIdentityId: identity ? identity.emailIdentityId : null, emailServerId: account.emailServerId,
    fromAddress: identity?.emailAddress || account.emailAddress, fromName: identity ? (identity.displayName ?? null) : (account.accountName ?? null),
    fromUserId: draft?.fromUserId || ec.user.userId, messageDate: ec.user.nowTimestamp, isRead: 'Y', sendError: null,
    scheduledSendDate: null}
if (toAddresses != null) fields.toAddresses = toAddresses || null
if (ccAddresses != null) fields.ccAddresses = ccAddresses || null
if (bccAddresses != null) fields.bccAddresses = bccAddresses || null
if (subject != null) fields.subject = subject
if (body != null) fields.body = body
if (bodyText != null) fields.bodyText = bodyText
if (parentEmailMessageId) {
    const parent = ec.entity.find(MESSAGE).condition('emailMessageId', parentEmailMessageId).one()
    if (parent == null || !access.accessMap[parent.emailAccountId]) { ec.message.addError(`Email message ${parentEmailMessageId} not found`); return }
    fields.parentEmailMessageId = parentEmailMessageId
    fields.rootEmailMessageId = parent.rootEmailMessageId || parent.emailMessageId
    const references = [].concat(String(parent.referencesHeader || '').split(/\s+/), parent.messageId ? [parent.messageId] : [])
            .filter((id) => id)
    // RFC 5322: the first id and the last ones, when the chain is long
    const kept = references.length > 20 ? [references[0]].concat(references.slice(-19)) : references
    fields.referencesHeader = kept.length ? kept.join(' ') : null
    fields.inReplyTo = isForward ? null : (parent.messageId ?? null)
    if (fields.subject == null && draft == null) {
        const parentSubject = parent.subject || ''
        const prefix = isForward ? 'Fwd: ' : 'Re: '
        fields.subject = /^(re|fwd?):/i.test(parentSubject) && !isForward ? parentSubject : prefix + parentSubject
    }
}
if (draft == null) {
    draft = ec.entity.makeValue(MESSAGE)
    draft.setSequencedIdPrimary()
    draft.setFields(fields, true, null, null)
} else {
    draft.setFields(fields, true, null, null)
}
const html = draft.body, text = draft.bodyText
draft.set('contentType', html ? 'text/html' : 'text/plain')
const snippet = textOf(text || html)
draft.set('snippet', snippet.length > 140 ? snippet.substring(0, 137) + '...' : snippet)
emailMessageId = draft.emailMessageId
let attachmentBytes = 0
if (attachmentList != null) {
    for (const attachment of attachmentList) if (!attachment || !attachment.attachmentLocation) {
        ec.message.addError('Each attachment needs its attachmentLocation'); return }
}
if (ec.entity.find(MESSAGE).condition('emailMessageId', emailMessageId).count() === 0) draft.create()
else draft.update()
if (attachmentList != null) {
    ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).deleteAll()
    for (const attachment of attachmentList) {
        const row = ec.entity.makeValue('moqui.basic.email.EmailMessageAttachment')
        row.setSequencedIdPrimary()
        const location = String(attachment.attachmentLocation)
        row.setFields({emailMessageId: emailMessageId, attachmentLocation: location,
            fileName: attachment.fileName || location.substring(location.lastIndexOf('/') + 1), fileSize: attachment.fileSize ?? null,
            contentType: attachment.contentType ?? null, contentId: attachment.contentId ?? null,
            isInline: attachment.isInline === true || attachment.isInline === 'Y' ? 'Y' : 'N'}, false, null, null)
        row.create()
    }
}
const attachments = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list())
for (const attachment of attachments) attachmentBytes += Number(attachment.fileSize || 0)
draft.set('hasAttachment', attachments.some((attachment) => attachment.isInline !== 'Y') ? 'Y' : 'N')
draft.set('messageSize', String(html || '').length + String(text || '').length + attachmentBytes)
draft.update()
rootEmailMessageId = draft.rootEmailMessageId ?? null

const MESSAGE = 'moqui.basic.email.EmailMessage'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
sent = false
messageId = null
sendError = null
statusId = null
const scheduleMillis = toMillis(scheduledSendDate)
scheduledSendDate = null
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
const draft = ec.entity.find(MESSAGE).condition('emailMessageId', emailMessageId).one()
if (draft == null || !access.accessMap[draft.emailAccountId]) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
const account = access.accountList.find((candidate) => candidate.emailAccountId === draft.emailAccountId)
if (!account.canSend) { ec.message.addError(`You may not send from email account ${draft.emailAccountId}`); return }
if (!(draft.statusId === 'ES_DRAFT' || (draft.statusId === 'ES_READY' && draft.sendError))) {
    ec.message.addError(`Email message ${emailMessageId} is not a draft`); return }
if (draft.emailIdentityId && ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailIdentityId', draft.emailIdentityId)
        .condition('emailAccountId', draft.emailAccountId).count() === 0) {
    ec.message.addError(`The identity of email message ${emailMessageId} is not of its account`); return }
const server = account.emailServerId ? ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', account.emailServerId).one() : null
if (server == null || !server.smtpHost) { ec.message.addError(`Email account ${account.accountName || account.emailAccountId} has no outgoing (SMTP) server`); return }
if (!draft.fromAddress) { ec.message.addError('The message has no from address'); return }
if (!draft.toAddresses) { ec.message.addError('Add a recipient in To'); return }
const bad = [draft.toAddresses, draft.ccAddresses, draft.bccAddresses].filter((list) => list)
        .flatMap((list) => String(list).split(',')).map((entry) => entry.trim()).filter((entry) => entry && !entry.includes('@'))
if (bad.length) { ec.message.addError(`Not an email address: ${bad.join(', ')}`); return }
if (!draft.body && !draft.bodyText) { ec.message.addError('The message has no body'); return }

const nowMillis = Number(ec.user.nowTimestamp)
let sendAt = null
if (scheduleMillis != null && scheduleMillis > nowMillis + 1000) sendAt = scheduleMillis
else if (holdSeconds > 0) sendAt = nowMillis + Math.min(holdSeconds, 300) * 1000
if (sendAt != null) {
    const claimed = ec.service.sync().name('org.moqui.impl.EmailClientServices.claim#DraftSend').parameters({
        emailMessageId: emailMessageId, toStatusId: 'ES_SCHEDULED', scheduledSendDate: new Date(sendAt)}).disableAuthz().call()
    if (ec.message.hasError()) return
    if (!claimed.claimed) { ec.message.addError(`Email message ${emailMessageId} is not a draft`); return }
    statusId = 'ES_SCHEDULED'
    scheduledSendDate = sendAt
    return
}
const result = ec.service.sync().name('org.moqui.impl.EmailClientServices.deliver#DraftMessage')
        .parameters({emailMessageId: emailMessageId, fromStatusIdList: ['ES_DRAFT', 'ES_READY']}).disableAuthz().call()
if (ec.message.hasError()) return
sent = result.sent === true
messageId = result.messageId ?? null
sendError = result.sendError ?? null
statusId = result.statusId ?? null

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
const message = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).forUpdate(true).one()
if (message == null || !access.accessMap[message.emailAccountId]) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
if (access.accessMap[message.emailAccountId] < 2) { ec.message.addError(`You may not change the mail of email account ${message.emailAccountId}`); return }
statusId = message.statusId
if (!(message.statusId === 'ES_SCHEDULED' || (message.statusId === 'ES_READY' && message.sendError))) {
    ec.message.addError(message.statusId === 'ES_SENT' || message.statusId === 'ES_READY'
            ? `Email message ${emailMessageId} is sent already` : `Email message ${emailMessageId} is not waiting to send`)
    return
}
const drafts = ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', message.emailAccountId)
        .condition('folderKindEnumId', 'EfkDrafts').orderBy('sequenceNum,emailFolderId').limit(1).list()
message.setFields({statusId: 'ES_DRAFT', scheduledSendDate: null, sendError: null, messageDate: ec.user.nowTimestamp,
    emailFolderId: drafts.length ? drafts[0].emailFolderId : null}, true, null, null)
message.update()
statusId = 'ES_DRAFT'

if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('record#SendResult is internal'); return }
const message = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).forUpdate(true).one()
if (message == null) return
if (sendError) {
    message.setFields({sendError: String(sendError).substring(0, 4000), emailFolderId: null}, true, null, null)
    if (message.statusId !== 'ES_SENT') message.set('statusId', 'ES_READY')
    message.update()
    statusId = message.statusId
    return
}
const sentFolders = ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', message.emailAccountId)
        .condition('folderKindEnumId', 'EfkSent').orderBy('sequenceNum,emailFolderId').limit(1).list()
message.setFields({statusId: 'ES_SENT', emailFolderId: sentFolders.length ? sentFolders[0].emailFolderId : null, isRead: 'Y',
    sendError: null, scheduledSendDate: null, messageDate: message.sentDate || ec.user.nowTimestamp,
    sentDate: message.sentDate || ec.user.nowTimestamp}, true, null, null)
if (messageId && !message.messageId) message.set('messageId', messageId)
message.update()
statusId = 'ES_SENT'
if (message.parentEmailMessageId && message.inReplyTo) {
    const parent = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', message.parentEmailMessageId).one()
    if (parent != null && parent.isAnswered !== 'Y') { parent.set('isAnswered', 'Y'); parent.update() }
}

sentCount = 0
failedCount = 0
const MESSAGE = 'moqui.basic.email.EmailMessage'
const nowMillis = Number(ec.user.nowTimestamp)
let ids
if (emailMessageId) {
    const message = ec.entity.find(MESSAGE).condition('emailMessageId', emailMessageId).one()
    const authzOff = ec.artifactExecution.authzDisabled()
    if (!authzOff) {
        const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
        if (ec.message.hasError()) return
        if (message == null || !access.accessMap[message.emailAccountId]) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
        if (access.accessMap[message.emailAccountId] < 2) { ec.message.addError(`You may not send from email account ${message.emailAccountId}`); return }
    }
    if (message == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    if (message.statusId !== 'ES_SCHEDULED' || !(Number(message.scheduledSendDate) <= nowMillis + 1000)) return
    ids = [emailMessageId]
} else {
    ids = Array.from(ec.entity.find(MESSAGE).condition('statusId', 'ES_SCHEDULED')
            .condition(ec.entity.conditionFactory.makeCondition('scheduledSendDate', 'less-equals', ec.user.nowTimestamp))
            .selectField('emailMessageId').orderBy('scheduledSendDate').orderBy('emailMessageId').limit(limit > 0 ? limit : 200).list())
            .map((row) => row.emailMessageId)
}
for (const id of ids) {
    ec.message.pushErrors()
    const result = ec.service.sync().name('org.moqui.impl.EmailClientServices.deliver#DraftMessage')
            .parameters({emailMessageId: id, fromStatusIdList: ['ES_SCHEDULED']}).disableAuthz().call()
    if (ec.message.hasError()) {
        ec.logger.log('error', `Could not send scheduled email message ${id}: ${ec.message.errorsString}`)
        failedCount++
    } else if (result.claimed && result.sent) sentCount++
    else if (result.claimed) failedCount++
    ec.message.clearErrors()
    ec.message.popErrors()
}

returnedCount = 0
failedCount = 0
const cf = ec.entity.conditionFactory
const rows = Array.from(ec.entity.find('moqui.basic.email.EmailMessage').condition('snoozedThruDate', 'not-equals', null)
        .condition(cf.makeCondition('snoozedThruDate', 'less-equals', ec.user.nowTimestamp))
        .selectField('emailMessageId').selectField('rootEmailMessageId').selectField('emailAccountId').selectField('messageDate')
        .orderBy('messageDate').limit(limit > 0 ? limit : 500).list())
const threads = {}
for (const row of rows) (threads[row.rootEmailMessageId || row.emailMessageId] ||= []).push(row)
const accounts = new Set()
for (const threadId of Object.keys(threads)) {
    const messages = threads[threadId]
    const ids = messages.map((row) => row.emailMessageId)
    ec.message.pushErrors()
    ec.service.sync().name('org.moqui.impl.EmailClientServices.unsnooze#Thread').parameters({emailMessageIdList: ids,
        unreadEmailMessageId: messages[messages.length - 1].emailMessageId}).disableAuthz().call()
    if (ec.message.hasError()) {
        ec.logger.log('error', `Could not bring back snoozed email thread ${threadId}: ${ec.message.errorsString}`)
        failedCount++
    } else {
        returnedCount += ids.length
        for (const row of messages) if (row.emailAccountId) accounts.add(row.emailAccountId)
    }
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (accounts.size) ec.service.sync().name('org.moqui.impl.EmailClientServices.publish#AccountCounts')
        .parameter('emailAccountIdList', Array.from(accounts)).disableAuthz().call()

if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('unsnooze#Thread is internal'); return }
for (const row of ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', 'in', emailMessageIdList).list()) {
    row.set('snoozedThruDate', null)
    if (row.emailMessageId === unreadEmailMessageId) row.set('isRead', 'N')
    row.update()
}

const cf = ec.entity.conditionFactory
unreadCount = 0
unreadThreadCount = 0
accountCountMap = {}
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').parameter('userId', userId).call()
if (ec.message.hasError()) return
const accountIds = access.accountList.filter((account) => !account.isInternal).map((account) => account.emailAccountId)
if (!accountIds.length) return
const inboxIds = Array.from(ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', 'in', accountIds)
        .condition('folderKindEnumId', 'EfkInbox').selectField('emailFolderId').list()).map((row) => row.emailFolderId)
if (!inboxIds.length) return
const now = ec.user.nowTimestamp
const threads = new Set()
for (const row of ec.entity.find('moqui.basic.email.EmailMessage').condition('emailFolderId', 'in', inboxIds)
        .condition(cf.makeCondition('isRead', 'not-equals', 'Y', true)).condition('archivedDate', null)
        .condition(cf.makeCondition([cf.makeCondition('snoozedThruDate', 'equals', null), cf.makeCondition('snoozedThruDate', 'less-equals', now)], 'or'))
        .selectField('emailMessageId').selectField('rootEmailMessageId').selectField('emailAccountId').list()) {
    unreadCount++
    threads.add(row.rootEmailMessageId || row.emailMessageId)
    accountCountMap[row.emailAccountId] = (accountCountMap[row.emailAccountId] || 0) + 1
}
unreadThreadCount = threads.size

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not add identities to email account ${emailAccountId}`); return }
if (access.account.isInternal) { ec.message.addError('The Internal account sends as the user'); return }
if (!String(emailAddress).includes('@')) { ec.message.addError(`Not an email address: ${emailAddress}`); return }
const others = Array.from(ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', emailAccountId).list())
const makeDefault = isDefault || others.length === 0
if (makeDefault) for (const other of others) if (other.isDefault === 'Y') { other.set('isDefault', 'N'); other.update() }
const identity = ec.entity.makeValue('moqui.basic.email.EmailIdentity')
identity.setSequencedIdPrimary()
identity.setFields({emailAccountId: emailAccountId, emailAddress: emailAddress, displayName: displayName, replyToAddress: replyToAddress,
    signatureHtml: signatureHtml, signaturePlacementEnumId: signaturePlacementEnumId, useForReplies: useForReplies ? 'Y' : 'N',
    isDefault: makeDefault ? 'Y' : 'N'}, false, null, null)
identity.create()
emailIdentityId = identity.emailIdentityId

const identity = ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailIdentityId', emailIdentityId).one()
const access = identity ? ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', identity.emailAccountId).call() : {level: 0}
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email identity ${emailIdentityId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not change email identity ${emailIdentityId}`); return }
if (emailAddress != null) {
    if (!String(emailAddress).includes('@')) { ec.message.addError(`Not an email address: ${emailAddress}`); return }
    identity.set('emailAddress', emailAddress)
}
const blank = (value) => value === '' ? null : value
if (displayName != null) identity.set('displayName', blank(displayName))
if (replyToAddress != null) identity.set('replyToAddress', blank(replyToAddress))
if (signatureHtml != null) identity.set('signatureHtml', blank(signatureHtml))
if (signaturePlacementEnumId != null) identity.set('signaturePlacementEnumId', blank(signaturePlacementEnumId))
if (useForReplies != null) identity.set('useForReplies', useForReplies ? 'Y' : 'N')
if (isDefault === true && identity.isDefault !== 'Y') {
    for (const other of ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', identity.emailAccountId)
            .condition('isDefault', 'Y').list()) { other.set('isDefault', 'N'); other.update() }
    identity.set('isDefault', 'Y')
}
identity.update()

const identity = ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailIdentityId', emailIdentityId).one()
const access = identity ? ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', identity.emailAccountId).call() : {level: 0}
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email identity ${emailIdentityId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not delete email identity ${emailIdentityId}`); return }
ec.entity.find('moqui.basic.email.EmailMessage').condition('emailIdentityId', emailIdentityId).updateAll({emailIdentityId: null})
const wasDefault = identity.isDefault === 'Y'
identity.delete()
if (wasDefault) {
    const next = ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', identity.emailAccountId)
            .orderBy('emailIdentityId').limit(1).list()
    if (next.length) { next[0].set('isDefault', 'Y'); next[0].update() }
}

outOfOffice = null
isActive = false
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
const row = ec.entity.find('moqui.basic.email.EmailOutOfOffice').condition('emailAccountId', emailAccountId).one()
if (row == null) return
const toMillis = (value) => value == null || value === '' ? null : Number(value)
outOfOffice = {emailAccountId: emailAccountId, enabled: row.enabled === 'Y', fromDate: toMillis(row.fromDate), thruDate: toMillis(row.thruDate),
    subject: row.subject ?? null, bodyHtml: row.bodyHtml ?? null, internalBodyHtml: row.internalBodyHtml ?? null,
    replyOncePerDays: row.replyOncePerDays ?? null}
const now = Number(ec.user.nowTimestamp)
isActive = outOfOffice.enabled && (outOfOffice.fromDate == null || outOfOffice.fromDate <= now) &&
        (outOfOffice.thruDate == null || outOfOffice.thruDate > now)

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
        .parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
if (access.level < 3) { ec.message.addError(`You may not change the automatic reply of email account ${emailAccountId}`); return }
if (access.account.isInternal) { ec.message.addError('The Internal account has no automatic reply'); return }
if (fromDate != null && thruDate != null && Number(thruDate) <= Number(fromDate)) { ec.message.addError('The automatic reply ends before it starts'); return }
if (enabled && !bodyHtml) { ec.message.addError('The automatic reply needs a message'); return }
const row = ec.entity.makeValue('moqui.basic.email.EmailOutOfOffice')
row.setFields({emailAccountId: emailAccountId, enabled: enabled ? 'Y' : 'N', fromDate: fromDate, thruDate: thruDate, subject: subject,
    bodyHtml: bodyHtml, internalBodyHtml: internalBodyHtml, replyOncePerDays: replyOncePerDays}, false, null, null)
row.createOrUpdate()

if (!ec.user.userId) { ec.message.addError('No user for the text block'); return }
if (userGroupId && ec.entity.find('moqui.security.UserGroupMember').condition('userId', ec.user.userId).condition('userGroupId', userGroupId)
        .conditionDate('fromDate', 'thruDate', null).disableAuthz().count() === 0) {
    ec.message.addError(`You are not in user group ${userGroupId}`); return }
const row = ec.entity.makeValue('moqui.basic.email.EmailTextBlock')
row.setSequencedIdPrimary()
row.setFields({ownerUserId: ec.user.userId, title: title, shortcut: shortcut, bodyHtml: bodyHtml, userGroupId: userGroupId || null},
        false, null, null)
row.create()
emailTextBlockId = row.emailTextBlockId

const row = ec.entity.find('moqui.basic.email.EmailTextBlock').condition('emailTextBlockId', emailTextBlockId).one()
if (row == null || row.ownerUserId !== ec.user.userId) { ec.message.addError(`Text block ${emailTextBlockId} not found`); return }
if (userGroupId && userGroupId !== row.userGroupId && ec.entity.find('moqui.security.UserGroupMember').condition('userId', ec.user.userId)
        .condition('userGroupId', userGroupId).conditionDate('fromDate', 'thruDate', null).disableAuthz().count() === 0) {
    ec.message.addError(`You are not in user group ${userGroupId}`); return }
if (title != null) {
    if (!title) { ec.message.addError('A text block needs a title'); return }
    row.set('title', title)
}
if (shortcut != null) row.set('shortcut', shortcut || null)
if (bodyHtml != null) row.set('bodyHtml', bodyHtml || null)
if (userGroupId != null) row.set('userGroupId', userGroupId || null)
row.update()

const row = ec.entity.find('moqui.basic.email.EmailTextBlock').condition('emailTextBlockId', emailTextBlockId).one()
if (row == null || row.ownerUserId !== ec.user.userId) { ec.message.addError(`Text block ${emailTextBlockId} not found`); return }
row.delete()

const row = ec.entity.find('moqui.basic.email.EmailSearch').condition('emailSearchId', emailSearchId).one()
if (row == null || row.ownerUserId !== ec.user.userId) { ec.message.addError(`Saved search ${emailSearchId} not found`); return }
row.delete()
